<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue';
import { application } from '../presentation/application/presentation-runtime.js';
import { clearFormDraft, hasFormDraft } from '../../js/ui/form-drafts.js';
import { timelineArea } from '../../js/ui/timeline.js';
const props=defineProps({mode:{type:String,default:'CREATE'},record:{type:Object,default:null},authoritativeOdometer:{type:[Number,String],default:null}});
const emit=defineEmits(['close','saved']); const formRef=ref(null),busy=ref(false),error=ref(''),success=ref(''),gpsStatus=ref('Waiting for location…'),lastPosition=ref(null),latestFuel=ref(null),loadingLatest=ref(false);
const draft=ref({odometer:'',pricePerKg:'',amount:'',recordedAt:new Date().toISOString(),locationName:'',locationArea:null}); let watchId=null,reverseTimer=null;
const isEdit=computed(()=>props.mode==='EDIT'||!!props.record); const title=computed(()=>isEdit.value?'Correct Fuel':'Quick Fuel'); const authoritative=computed(()=>props.authoritativeOdometer==null||props.authoritativeOdometer===''?null:Number(props.authoritativeOdometer)); const quantityKg=computed(()=>{const a=Number(draft.value.amount),p=Number(draft.value.pricePerKg);return a>0&&p>0?a/p:null}); const timestampLabel=computed(()=>new Date(draft.value.recordedAt).toLocaleString()); const draftKey=computed(()=>isEdit.value?`fuel:edit:${props.record?.entityId||props.record?.id||'unknown'}`:'fuel:create');
function iso(){return new Date().toISOString()}
function loadRecord(r){const x=r||{};draft.value={odometer:x.odometer??'',pricePerKg:x.pricePerKg??x.price_per_kg??'',amount:x.amount??(x.amount_paise!=null?Number(x.amount_paise)/100:''),recordedAt:x.occurredAt||x.recorded_at||x.date||iso(),locationName:x.locationName??x.location_name??'',locationArea:x.locationArea??x.location_area??null}}
function reverseGeocode(position){clearTimeout(reverseTimer);reverseTimer=setTimeout(async()=>{const {latitude,longitude}=position.coords;try{const response=await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${encodeURIComponent(latitude)}&lon=${encodeURIComponent(longitude)}`,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error();const data=await response.json(),a=data.address||{},name=data.display_name||[a.suburb,a.city_district,a.city,a.town,a.village].filter(Boolean).join(', ')||null;draft.value.locationName=name||'';draft.value.locationArea=timelineArea({locationName:name,locationArea:null});gpsStatus.value=name?`Location captured · ${name}`:`Location captured · ${latitude.toFixed(5)}, ${longitude.toFixed(5)}`}catch{gpsStatus.value=`Location captured · ${latitude.toFixed(5)}, ${longitude.toFixed(5)}`}},100)}
function onPosition(position){lastPosition.value=position;gpsStatus.value='Location captured';reverseGeocode(position)}
function startLocation(){if(!navigator.geolocation){gpsStatus.value='Location unavailable on this device/browser';return}navigator.geolocation.getCurrentPosition(onPosition,()=>{gpsStatus.value='Location permission unavailable'},{enableHighAccuracy:false,maximumAge:30000,timeout:1500});watchId=navigator.geolocation.watchPosition(onPosition,()=>{}, {enableHighAccuracy:false,maximumAge:30000,timeout:1500})}
function stopLocation(){if(watchId!==null&&navigator.geolocation)navigator.geolocation.clearWatch(watchId);watchId=null;clearTimeout(reverseTimer)}
async function loadLatest(){if(isEdit.value)return;loadingLatest.value=true;try{const rows=await application.listFuel();latestFuel.value=(Array.isArray(rows)?rows:[]).filter(r=>!r.is_deleted).sort((a,b)=>String(b.recorded_at||b.created_at||'').localeCompare(String(a.recorded_at||a.created_at||'')))[0]||null}catch{latestFuel.value=null}finally{loadingLatest.value=false}}
function validate(){const o=Number(draft.value.odometer),p=Number(draft.value.pricePerKg),a=Number(draft.value.amount);if(!Number.isInteger(o)||o<0)return'Enter a valid odometer.';if(!isEdit.value&&authoritative.value!=null&&o<authoritative.value)return'Fuel odometer cannot be below the authoritative odometer.';if(!Number.isFinite(p)||p<=0)return'Enter a valid price per kg.';if(!Number.isFinite(a)||a<=0)return'Enter a valid amount.';return''}
async function save(){if(busy.value)return;const v=validate();if(v){error.value=v;return}busy.value=true;error.value='';try{const recordedAt=iso();draft.value.recordedAt=recordedAt;const p=lastPosition.value;let result;if(isEdit.value){result=await application.saveHistoricalCorrection({entityType:'Fuel',entityId:props.record?.entityId||props.record?.id},{recordedAt,odometer:Number(draft.value.odometer),pricePerKg:Number(draft.value.pricePerKg),amount:Number(draft.value.amount),locationName:draft.value.locationName||null,locationArea:draft.value.locationArea||null})}else{result=await application.recordFuel({odometer:Number(draft.value.odometer),price_per_kg:Number(draft.value.pricePerKg),amount_paise:Math.round(Number(draft.value.amount)*100),recorded_at:recordedAt,date:recordedAt.slice(0,10),scope:'BUSINESS',entry_source:'FUEL',latitude:p?.coords?.latitude??null,longitude:p?.coords?.longitude??null,location_name:draft.value.locationName||null,location_area:draft.value.locationArea||null})}clearFormDraft(formRef.value);success.value=isEdit.value?'Fuel record updated successfully.':'Fuel record saved successfully.';emit('saved',result);emit('close')}catch(e){error.value=String(e?.message||e)}finally{busy.value=false}}
function cancel(){if(busy.value)return;if(formRef.value&&hasFormDraft(formRef.value)){const ok=globalThis.confirm?.('Discard this unsaved draft?');if(ok===false)return}clearFormDraft(formRef.value);emit('close')}
function closeOverlay(){if(busy.value)return;const ok=globalThis.confirm?.('Close Quick Fuel? Any unsaved entries will be lost.');if(ok===false)return;clearFormDraft(formRef.value);emit('close')}
function onKey(e){if(e.key==='Escape')closeOverlay()}
if(isEdit.value)loadRecord(props.record); onMounted(()=>{window.addEventListener('keydown',onKey);if(!isEdit.value){loadLatest();startLocation()}}); onUnmounted(()=>{window.removeEventListener('keydown',onKey);stopLocation()})
</script>
<template><div class="fuel-form-overlay" role="dialog" aria-modal="true" :aria-label="title"><form ref="formRef" class="fuel-form-card" data-kfe-draft-form="true" data-kfe-form-architecture="universal" data-form-type="default" :data-kfe-draft-key="draftKey" @submit.prevent="save"><header class="fuel-form-header"><div><p class="fuel-eyebrow">KFE 2.0 · FUEL</p><h2>{{title}}</h2></div><button type="button" class="kfe-qf-close" :disabled="busy" aria-label="Close Quick Fuel" @click="closeOverlay">×</button></header><section v-if="!isEdit&&!loadingLatest&&latestFuel" class="last-fuel-entry"><strong>{{Number(latestFuel.quantity_kg||0).toFixed(3)}} kg · ₹{{Number(latestFuel.amount_paise||0)/100}}</strong><span>Odometer {{latestFuel.odometer}}</span></section><p class="fuel-form-help">Date/time and optional location are captured automatically without blocking the save.</p><label data-kfe-field><span class="fuel-floating-label">Odometer *</span><input v-model="draft.odometer" inputmode="numeric" type="number" min="0" step="1" required></label><label data-kfe-field><span class="fuel-floating-label">Price per kg *</span><input v-model="draft.pricePerKg" inputmode="decimal" type="number" min="0" step="0.01" required></label><label data-kfe-field><span class="fuel-floating-label">Amount *</span><input v-model="draft.amount" inputmode="decimal" type="number" min="0" step="0.01" required></label><div class="fuel-calculated"><span>Refuelled kg</span><strong>{{quantityKg==null?'—':quantityKg.toFixed(3)+' kg'}}</strong></div><div class="fuel-meta"><span>🕒 {{timestampLabel}}</span><span>📍 {{draft.locationName||'Location unavailable'}}</span><small>{{gpsStatus}}</small></div><p v-if="error" class="kfe-qf-error" role="alert">{{error}}</p><p v-if="success" class="kfe-qf-success" role="status">✓ {{success}}</p><div class="fuel-actions"><button type="button" class="secondary-action" :disabled="busy" @click="cancel">Cancel</button><button type="submit" class="kfe-qf-swipe-track" :disabled="busy||!!success">{{busy?'Saving…':isEdit?'Save correction':'Save Fuel →'}}</button></div></form></div></template>
<style scoped>
.fuel-form-overlay{position:fixed;inset:0;z-index:2000;display:grid;place-items:center;padding:max(12px,env(safe-area-inset-top)) max(12px,env(safe-area-inset-right)) calc(112px + env(safe-area-inset-bottom) + var(--kfe-keyboard-inset,0px)) max(12px,env(safe-area-inset-left));background:rgba(0,0,0,.58);backdrop-filter:blur(12px);overflow:auto}.fuel-form-card{width:min(34rem,100%);max-height:min(92dvh,100%);overflow:auto;box-sizing:border-box;padding:18px;border:1px solid var(--kfe-ui-border,#303640);border-radius:22px;background:var(--kfe-ui-surface,#101419);color:var(--kfe-ui-text,#f7f9fb);box-shadow:0 20px 60px rgba(0,0,0,.4)}.fuel-form-header{display:flex;justify-content:space-between;align-items:flex-start;gap:1rem}.fuel-form-header h2{margin:.2rem 0 1rem}.fuel-eyebrow{margin:0;font-size:.75rem;font-weight:800;letter-spacing:.08em;color:var(--kfe-accent,#5ee6a8)}.kfe-qf-close{width:44px;height:44px;border:1px solid var(--kfe-ui-border,#303640);border-radius:12px;background:var(--kfe-ui-bg,#080a0d);color:inherit;font-size:1.5rem}.fuel-form-help{font-size:.78rem;color:var(--kfe-ui-muted,#a5adba)}.last-fuel-entry{display:grid;gap:4px;margin-bottom:12px;padding:12px;border:1px solid var(--kfe-ui-border,#303640);border-radius:14px;background:var(--kfe-ui-bg,#080a0d)}.last-fuel-entry span{font-size:.75rem;color:var(--kfe-ui-muted,#a5adba)}.fuel-form-card label{position:relative;display:grid;gap:5px;margin:14px 0;padding:10px 11px 8px;border:1px solid var(--kfe-ui-border,#303640);border-radius:16px;background:var(--kfe-ui-bg,#080a0d);min-height:78px}.fuel-floating-label{position:absolute;left:12px;top:7px;font-size:.67rem;font-weight:850;color:var(--kfe-ui-muted,#a5adba);pointer-events:none}.fuel-form-card input{width:100%;box-sizing:border-box;min-height:52px;margin-top:15px;padding:10px 11px;border:0;border-radius:10px;background:transparent;color:inherit;font-size:18px;outline:none}.fuel-form-card label:focus-within{border-color:var(--kfe-accent,#5ee6a8);box-shadow:0 0 0 3px color-mix(in srgb,var(--kfe-accent,#5ee6a8) 18%,transparent)}.fuel-calculated,.fuel-meta{display:flex;justify-content:space-between;gap:.75rem;align-items:center;padding:.8rem 0;border-top:1px solid var(--kfe-ui-border,#303640)}.fuel-meta{flex-wrap:wrap;font-size:.78rem;color:var(--kfe-ui-muted,#a5adba)}.fuel-meta small{width:100%;opacity:.85}.kfe-qf-error{padding:.7rem;border-radius:10px;background:#4b1717;color:#ffd6d6}.kfe-qf-success{padding:.8rem;border-radius:10px;background:#123d24;color:#c8f7d7;font-weight:800}.fuel-actions{display:flex;align-items:center;justify-content:flex-end;gap:.7rem;margin-top:1rem}.secondary-action{min-height:52px;padding:.72rem 1rem;border-radius:12px;border:1px solid var(--kfe-ui-border,#303640);background:var(--kfe-ui-bg,#080a0d);color:inherit}.kfe-qf-swipe-track{min-width:11rem;min-height:52px;padding:.8rem 1rem;border-radius:999px;border:1px solid var(--kfe-accent,#5ee6a8);background:var(--kfe-accent,#5ee6a8);color:#07130c;font-weight:900}.kfe-qf-swipe-track:disabled{opacity:.55}
</style>
